from cryptography.hazmat.primitives.ciphers.aead import AESGCM


class Solver:
    def __init__(self):
        self._buf = None
        self._aes = {}

    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        aad = problem["associated_data"]

        k = bytes(key)
        aes = self._aes.get(k)
        if aes is None:
            aes = AESGCM(k)
            self._aes[k] = aes

        n = len(plaintext)
        buf = self._buf
        if buf is None or len(buf) != n + 16:
            buf = bytearray(n + 16)
            self._buf = buf

        aes.encrypt_into(nonce, plaintext, aad, buf)
        return {"ciphertext": bytes(buf[:-16]), "tag": bytes(buf[-16:])}

