static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60000L * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char key[16], iv[12], aad[32], tag[16];
    memset(pt, 1, n);
    memset(key, 2, 16);
    memset(iv, 3, 12);
    memset(aad, 4, 32);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_aes_128_gcm();

    /* warmup */
    int len = 0, ctlen = 0;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
    ctlen = len;
    EVP_EncryptFinal_ex(ctx, ct + len, &len);
    ctlen += len;
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    int iters = 5;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("reuse ctx: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n / ((t1-t0)/iters) / 1e6);

    /* fresh ctx each time */
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(c, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(c, NULL, NULL, key, iv);
        EVP_EncryptUpdate(c, NULL, &len, aad, 32);
        EVP_EncryptUpdate(c, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(c, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(c);
    }
    t1 = now();
    printf("fresh ctx: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n / ((t1-t0)/iters) / 1e6);

    /* no aad */
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("reuse ctx no aad: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n / ((t1-t0)/iters) / 1e6);

    /* AES-256 */
    unsigned char key32[32];
    memset(key32, 5, 32);
    EVP_CIPHER_CTX_free(ctx);
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL);
