    }
    t1 = now();
    printf("AES-256 reuse no aad: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n / ((t1-t0)/iters) / 1e6);

    printf("ctlen %d tag0 %02x\n", ctlen, tag[0]);
    return 0;
}
