            EVP_EncryptUpdate(ctx, ct+off, &len, pt+off, cl);
        }
        EVP_EncryptFinal_ex(ctx, ct, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("AES-128-GCM 1MB chunks: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n/((t1-t0)/iters)/1e6);

    /* memcpy bandwidth */
    t0 = now();
    for (int i = 0; i < iters; i++) memcpy(ct, pt, n);
    t1 = now();
    printf("memcpy: %.4f s  %.1f MB/s\n", (t1-t0)/iters, n/((t1-t0)/iters)/1e6);

    return 0;
}
