#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    /* pin to cpu 0 */
    pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);

    size_t n = 60000L*1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n+64);
    unsigned char key[32], iv[16], tag[16];
    memset(pt, 1, n); memset(key, 2, 32); memset(iv, 3, 16);
    int len;

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);

    /* warmup */
    for (int i = 0; i < 2; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct+len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }

    int iters = 8;
    double best = 1e9, sum = 0;
    for (int i = 0; i < iters; i++) {
        double t0 = now();
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct+len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        double dt = now()-t0;
        if (dt < best) best = dt;
        sum += dt;
        printf("  iter %d: %.4f s  %.1f MB/s\n", i, dt, n/dt/1e6);
    }
    printf("best %.4f s %.1f MB/s   avg %.4f s %.1f MB/s\n", best, n/best/1e6, sum/iters, n/(sum/iters)/1e6);
    return 0;
}
