#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <immintrin.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

/* AES-128 key expansion (encrypt) */
static void expand128(const uint8_t key[16], __m128i rk[11]) {
    __m128i t = _mm_loadu_si128((const __m128i*)key);
    rk[0] = t;
    const int rcon[10] = {0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36};
    for (int i = 0; i < 10; i++) {
        __m128i s = _mm_aeskeygenassist_si128(t, rcon[i]);
        s = _mm_shuffle_epi32(s, 0xff);
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4));
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4));
        t = _mm_xor_si128(t, _mm_slli_si128(t, 4));
        t = _mm_xor_si128(t, s);
        rk[i+1] = t;
