static inline __m128i ghash_reduce(__m128i lo, __m128i hi) {
    /* reduce 256-bit product (hi:lo) modulo x^128+x^7+x^2+x+1 in reflected form */
    __m128i t = _mm_srli_epi64(lo, 63);
