    /* reduction polynomial reflected: 0xe1 << 120 */
    const __m128i poly = _mm_set_epi32(0xe1000000, 0, 0, 0);
    __m128i a = _mm_clmulepi64_si128(lo, poly, 0x00); /* lo.low * poly */
