}

/*
 * Karatsuba-free schoolbook GHASH multiply + reduction, reflected representation.
 * Algorithm from Intel clmul app note / OpenSSL gcm_ghash_clmul.
 * X and H are byte-swapped (reflected) blocks.
 */
static inline __m128i gfmul(__m128i X, __m128i H) {
    __m128i lo = _mm_clmulepi64_si128(X, H, 0x00);
    __m128i hi = _mm_clmulepi64_si128(X, H, 0x11);
    __m128i m1 = _mm_clmulepi64_si128(X, H, 0x10);
    __m128i m2 = _mm_clmulepi64_si128(X, H, 0x01);
    __m128i mid = _mm_xor_si128(m1, m2);
    lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
    /* reduction */
    const __m128i poly = _mm_set_epi32(0, 0, 0, 0xe1000000); /* reflected poly in low dword? */
    /* Use two-phase reduction from Intel whitepaper (reflected): */
    __m128i t1 = _mm_slli_epi64(lo, 1);
    __m128i t2 = _mm_slli_epi64(lo, 2);
    __m128i t7 = _mm_slli_epi64(lo, 7);
    __m128i r = _mm_xor_si128(_mm_xor_si128(t1, t2), t7);
    /* shift r left by 1 byte boundary: the bits that overflow each 64-bit lane */
    __m128i r_hi = _mm_srli_si128(r, 8);          /* overflow of low lane -> high lane position? not quite */
    (void)r_hi; (void)poly; (void)hi;
