    __m128i v1 = _mm_srli_epi64(lo, 63);
    __m128i v2 = _mm_srli_epi64(lo, 62);
    __m128i v7 = _mm_srli_epi64(lo, 57);
    __m128i v = _mm_xor_si128(_mm_xor_si128(v1, v2), v7);
    lo = _mm_xor_si128(lo, _mm_slli_epi64(_mm_xor_si128(_mm_xor_si128(
            _mm_slli_epi64(lo,1), _mm_slli_epi64(lo,2)), _mm_slli_epi64(lo,7)), 0));
