    __m128i vs = _mm_slli_si128(v, 8);
    lo = _mm_xor_si128(lo, vs);
    __m128i vr = _mm_srli_si128(v, 8);
    hi = _mm_xor_si128(hi, vr);
    /* phase 2 */
    __m128i w1 = _mm_slli_epi64(lo, 1);
    __m128i w2 = _mm_slli_epi64(lo, 2);
    __m128i w7 = _mm_slli_epi64(lo, 7);
    lo = _mm_xor_si128(lo, _mm_xor_si128(w1, _mm_xor_si128(w2, w7)));
