{"command":"cd aesbench && cat > mt_bench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

typedef struct { unsigned char *pt, *ct, *key, *iv; size_t n; int iters; } job;

static void *worker(void *arg) {
    job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    unsigned char tag[16];
    int len;
    for (int i = 0; i < j->iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->iv);
        EVP_EncryptUpdate(ctx, j->ct, &len, j->pt, (int)j->n);
        EVP_EncryptFinal_ex(ctx, j->ct+len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    int threads = atoi(getenv("T") ? getenv("T") : "4");
    size_t total = 60000L*1024;
    size_t chunk = total / threads;
    chunk -= chunk % 16;
    unsigned char key[16], iv[12];
    memset(key, 2, 16); memset(iv, 3, 12);
    job *jobs = calloc(threads, sizeof(job));
    for (int t = 0; t < threads; t++) {
        jobs[t].n = chunk;
        jobs[t].pt = malloc(chunk);
        jobs[t].ct = malloc(chunk+16);
        memset(jobs[t].pt, 1, chunk);
        jobs[t].key = key; jobs[t].iv = iv;
        jobs[t].iters = 1;
    }
    /* warmup */
    pthread_t *th = calloc(threads, sizeof(pthread_t));
    for (int t = 0; t < threads; t++) pthread_create(&th[t], NULL, worker, &jobs[t]);
    for (int t = 0; t < threads; t++) pthread_join(th[t], NULL);

    int rounds = 4;
    for (int t = 0; t < threads; t++) jobs[t].iters = rounds;
    double t0 = now();
    for (int t = 0; t < threads; t++) pthread_create(&th[t], NULL, worker, &jobs[t]);
    for (int t = 0; t < threads; t++) pthread_join(th[t], NULL);
    double dt = (now()-t0)/rounds;
    double bytes = (double)chunk * threads;
    printf("threads %d  %.4f s  %.1f MB/s aggregate (%.1f MB/s per thread)\n",
           threads, dt, bytes/dt/1e6, chunk/dt/1e6);
    return 0;
}
EOF
